 "content": "def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) < 2:
        return out
    # The marker belonging to the colored pattern is the one with nearby
    # nonzero cells; the other is the destination marker.
    def neighborhood_score(pos):
        r, c = pos
        return sum(
            1 for rr, row in enumerate(grid) for cc, v in enumerate(row)
            if v != 0 and (rr, cc) != pos and abs(rr-r) <= 3 and abs(cc-c) <= 3
        )
    source = max(markers, key=neighborhood_score)
    target = min((p for p in markers if p != source), key=neighborhood_score)
    dr, dc = target[0] - source[0], target[1] - source[1]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != 0 and (r, c) != source and (r, c) != target:
                rr, cc = r + dr, c + dc
                if 0 <= rr < len(grid) and 0 <= cc < len(row):
                    out[rr][cc] = v
    return out
